  if(tree){$$('[data-category-id]',tree).forEach(group=>{if(state&&Object.hasOwn(state.groups,group.dataset.categoryId))group.open=state.groups[group.dataset.categoryId];});tree.scrollTop=state?.treeScroll??0;}
